  aS/=8; iS/=8; fS/=8;
  let fbm = 0, amp = 1, freq = 0.035;
  for(let i=0;i<4;i++){fbm+=Math.sin(sx*freq+sy*freq*0.7+t*(0.5+i*0.3)+i*1.7)*amp;amp*=0.5;freq*=2.1;}
